CREATE TABLE research_input_snapshot(id uuid PRIMARY KEY,series_id text NOT NULL REFERENCES macro_series(id),as_of timestamptz NOT NULL,rule_id text NOT NULL,rule_version text NOT NULL,inputs jsonb NOT NULL,report jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(series_id,as_of,rule_id,rule_version));
CREATE TRIGGER research_snapshot_immutable BEFORE UPDATE OR DELETE ON research_input_snapshot FOR EACH ROW EXECUTE FUNCTION protect_raw_evidence();
CREATE TABLE relation_assessment(id bigserial PRIMARY KEY,relation_id uuid NOT NULL REFERENCES entity_relation(id),method text NOT NULL CHECK(method='AUTOMATED_EVIDENCE_AUDIT'),rule_version text NOT NULL,assessment text NOT NULL CHECK(assessment IN('PENDING','SUFFICIENT','INSUFFICIENT','CONFIRMED','REJECTED','EXPIRED')),evidence_id uuid NOT NULL REFERENCES raw_evidence(id),checks jsonb NOT NULL,limitations text NOT NULL,assessed_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TRIGGER relation_assessment_immutable BEFORE UPDATE OR DELETE ON relation_assessment FOR EACH ROW EXECUTE FUNCTION protect_raw_evidence();
